import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import ResponsiveImage from '../../../components/ResponsiveImage';

const banners = [
  {
    id: 1,
    image: '/images/optimized/img-e3279666ed4c-1024.webp',
    title: 'Artisan Coffee Excellence',
    subtitle: 'Handcrafted espresso from the world\'s finest single-origin beans'
  },
  {
    id: 2,
    image: '/images/optimized/img-43021c8d70b4-640.webp',
    title: 'Indulgence Redefined',
    subtitle: 'Experience the finest hot chocolate crafted with premium Belgian cocoa'
  },
  {
    id: 3,
    image: '/images/optimized/img-1503eba73c58-640.webp',
    title: 'Decadent Creations',
    subtitle: 'Signature desserts that redefine chocolate indulgence'
  },
  {
    id: 4,
    image: '/images/optimized/img-471d7a57ef01-640.webp',
    title: 'Barista Perfection',
    subtitle: 'Every creation is a masterpiece of flavor and artistry'
  }
];

export default function Hero() {
  const [currentBanner, setCurrentBanner] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentBanner((prev) => (prev + 1) % banners.length);
    }, 5000);
    return () => clearInterval(interval);
  }, []);

  const handleOrderClick = () => {
    window.REACT_APP_NAVIGATE('/find-store');
  };

  const handleAboutClick = () => {
    const craftSection = document.getElementById('about-us');
    if (craftSection) {
      craftSection.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <section className="relative h-screen w-full overflow-hidden">
      <AnimatePresence mode="wait">
        <motion.div
          key={currentBanner}
          className="absolute inset-0"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          transition={{ duration: 1, ease: 'easeInOut' }}
        >
          <div className="absolute inset-0">
            <ResponsiveImage
              src={banners[currentBanner].image}
              alt={banners[currentBanner].title}
              className="w-full h-full object-cover"
              sizes="100vw"
              priority
            />
          </div>
          <div className="absolute inset-0 bg-gradient-to-r from-black/85 via-black/60 to-black/20"></div>
        </motion.div>
      </AnimatePresence>

      {/* Content - Left Aligned */}
      <div className="relative z-10 h-full flex items-center">
        <div className="max-w-[1920px] mx-auto px-8 w-full">
          <div className="max-w-2xl">
            <AnimatePresence mode="wait">
              <motion.div
                key={currentBanner}
                initial={{ opacity: 0, y: 30 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -30 }}
                transition={{ duration: 0.8, ease: 'easeInOut' }}
              >
                <h1
                  className="font-['Syncopate'] text-3xl sm:text-4xl md:text-5xl font-bold text-[#F8F4F0] mb-4 leading-tight px-2 sm:px-0"
                  style={{
                    textShadow: '0 0 18px rgba(197, 160, 33, 0.5), 0 0 36px rgba(197, 160, 33, 0.25)'
                  }}
                >
                  {banners[currentBanner].title}
                </h1>

                <p className="font-['Outfit'] text-lg md:text-xl text-[#F8F4F0]/90 mb-8 md:mb-12 leading-relaxed px-2 sm:px-0">
                  {banners[currentBanner].subtitle}
                </p>
              </motion.div>
            </AnimatePresence>

            <motion.div
              className="flex flex-col sm:flex-row items-stretch sm:items-center gap-4 sm:gap-6 px-4 sm:px-0"
              initial={{ opacity: 0, y: 30 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.8, delay: 0.3 }}
            >
              <motion.button
                onClick={handleOrderClick}
                className="px-8 md:px-10 py-3 md:py-4 bg-gradient-to-r from-[#C5A021] to-[#D4AF37] text-[#140B07] font-['Syncopate'] font-bold text-xs md:text-sm tracking-wider rounded-full cursor-pointer whitespace-nowrap relative overflow-hidden group will-change-temp"
                whileHover={{ scale: 1.04 }}
                whileTap={{ scale: 0.95 }}
              >
                <span className="relative z-10 uppercase">Order Now</span>
                <motion.div
                  className="absolute inset-0 bg-gradient-to-r from-[#D4AF37] to-[#C5A021]"
                  initial={{ x: '-100%' }}
                  whileHover={{ x: 0 }}
                  transition={{ duration: 0.3 }}
                />
              </motion.button>

              <motion.button
                onClick={handleAboutClick}
                className="px-8 md:px-10 py-3 md:py-4 border-2 border-[#C5A021] text-[#F8F4F0] font-['Syncopate'] font-bold text-xs md:text-sm tracking-wider rounded-full cursor-pointer whitespace-nowrap relative overflow-hidden group"
                whileHover={{ scale: 1.03 }}
                whileTap={{ scale: 0.95 }}
              >
                <span className="relative z-10 uppercase">About Us</span>
              </motion.button>
            </motion.div>
          </div>
        </div>
      </div>

      {/* Banner Indicators - Centered */}
      <div className="absolute bottom-12 left-1/2 -translate-x-1/2 z-20 flex gap-3">
        {banners.map((_, index) => (
          <motion.button
            key={index}
            onClick={() => setCurrentBanner(index)}
            className={`w-12 h-1 rounded-full cursor-pointer transition-all duration-300 ${index === currentBanner
              ? 'bg-[#C5A021]'
              : 'bg-[#F8F4F0]/30 hover:bg-[#F8F4F0]/50'
              }`}
            whileHover={{ scale: 1.1 }}
            whileTap={{ scale: 0.95 }}
          />
        ))}
      </div>

      {/* Scroll Indicator */}
      <motion.div
        className="absolute bottom-12 right-8 z-20 flex flex-col items-center gap-2"
        animate={{ y: [0, 10, 0] }}
        transition={{ duration: 2, repeat: Infinity }}
      >
        <span className="text-[#F8F4F0]/60 text-xs font-['Outfit'] tracking-widest rotate-90 origin-center">
          SCROLL
        </span>
        <div className="w-px h-16 bg-gradient-to-b from-[#C5A021] to-transparent"></div>
      </motion.div>
    </section>
  );
}
