import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useCart } from '../../../context/CartContext';
import { useWishlist } from '../../../context/WishlistContext';
import ResponsiveImage from '../../../components/ResponsiveImage';
import { commonShadow } from '../../../utils/uiEffects';

export default function Merchandise() {
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [selectedVariant, setSelectedVariant] = useState({ size: 'M', color: 'Brown' });
  const [quantity, setQuantity] = useState(1);
  const { addToCart } = useCart();
  const { toggleWishlist, isInWishlist } = useWishlist();

  // Reset quantity when modal opens/closes
  useEffect(() => {
    if (selectedProduct) {
      setQuantity(1);
    }
  }, [selectedProduct]);

  const products = [
    {
      id: 'm1',
      name: 'TCR Premium Coffee Beans',
      price: 850,
      image: '/images/optimized/img-b48d666ab063-640.webp',
      stock: 15,
      variants: { sizes: ['250g', '500g', '1kg'], colors: [] }
    },
    {
      id: 'm2',
      name: 'TCR Ceramic Mug',
      price: 450,
      image: '/images/optimized/img-c09223a94752-640.webp',
      stock: 2,
      variants: { sizes: [], colors: ['Brown', 'Cream', 'Black'] }
    },
    {
      id: 'm3',
      name: 'TCR Signature Hoodie',
      price: 1299,
      image: '/images/optimized/img-e698e7714b9a-640.webp',
      stock: 8,
      variants: { sizes: ['S', 'M', 'L', 'XL'], colors: ['Brown', 'Cream', 'Black'] }
    },
    {
      id: 'm4',
      name: 'Chocolate Gift Box',
      price: 1200,
      image: '/images/optimized/img-b982618039d4-640.webp',
      stock: 12,
      variants: { sizes: [], colors: [] }
    },
    {
      id: 'm5',
      name: 'TCR Travel Tumbler',
      price: 650,
      image: '/images/optimized/img-21a25bd61b2e-640.webp',
      stock: 20,
      variants: { sizes: [], colors: ['Brown', 'Gold', 'Silver'] }
    },
    {
      id: 'm6',
      name: 'Artisan Chocolate Bar Set',
      price: 950,
      image: '/images/optimized/img-f197eb8e72c8-640.webp',
      stock: 18,
      variants: { sizes: [], colors: [] }
    }
  ];

  return (
    <section id="merchandise" className="relative py-16 px-4 md:px-8">
      <div className="max-w-7xl mx-auto">
        <motion.div
          className="text-center mb-12"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
        >
          <h2 className="text-3xl md:text-4xl font-serif text-[#C5A021] mb-3">Merchandise</h2>
          <p className="text-lg text-[#F8F4F0]/70 font-light">Take the experience home</p>
        </motion.div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8" data-product-shop>
          {products.map((product, index) => (
            <motion.div
              key={product.id}
              className={`group relative bg-[#25160F]/50 backdrop-blur-sm rounded-xl border border-[#C5A021]/15 overflow-hidden cursor-pointer ${commonShadow}`}
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: index * 0.08 }}
              whileHover={{ translateY: -6, scale: 1.01 }}
              onClick={() => setSelectedProduct(product)}
            >
              <div className="relative w-full h-56 overflow-hidden">
                <ResponsiveImage
                  src={product.image}
                  alt={product.name}
                  className="w-full h-full object-cover object-top"
                  sizes="(max-width: 1024px) 100vw, 33vw"
                />
                {product.stock <= 5 && (
                  <div className="absolute top-4 right-4 px-3 py-1 bg-gradient-to-r from-[#C5A021] to-red-500 text-[#140B07] text-xs font-semibold rounded-full whitespace-nowrap">
                    Only {product.stock} left
                  </div>
                )}
              </div>

              <div className="p-4">
                <h3 className="text-lg font-semibold text-[#F8F4F0] mb-2">{product.name}</h3>
                <div className="flex items-center justify-between">
                  <span className="text-lg font-bold text-[#C5A021]">₹{product.price}</span>
                  <motion.button
                    className="px-4 py-2 bg-[#C5A021] text-[#140B07] rounded-full text-sm font-semibold cursor-pointer whitespace-nowrap"
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                    onClick={(e) => {
                      e.stopPropagation();
                      setSelectedProduct(product);
                    }}
                  >
                    Quick View
                  </motion.button>
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      </div>

      <AnimatePresence>
        {selectedProduct && (
          <motion.div
            className="fixed inset-0 bg-black/80 backdrop-blur-sm z-[1000] flex items-center justify-center p-4"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setSelectedProduct(null)}
          >
            <motion.div
              className="glass-panel-strong rounded-2xl border-2 border-gold max-w-md w-full max-h-[85vh] overflow-hidden flex flex-col"
              initial={{ scale: 0.8, y: 50 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.8, y: 50 }}
              onClick={(e) => e.stopPropagation()}
            >
              {/* Close Button */}
              <div className="absolute top-3 right-3 z-10">
                <motion.button
                  onClick={() => setSelectedProduct(null)}
                  className="w-8 h-8 rounded-full bg-cocoa-dark/80 border border-gold/20 flex items-center justify-center cursor-pointer hover:border-gold"
                  whileHover={{ scale: 1.1, rotate: 90 }}
                  whileTap={{ scale: 0.9 }}
                >
                  <i className="ri-close-line text-cream text-lg"></i>
                </motion.button>
              </div>

              {/* Scrollable Content Area */}
              <div className="flex-1 overflow-y-auto px-6 pt-6 pb-4">
                {/* Product Image */}
                <div className="relative w-full h-48 rounded-xl overflow-hidden mb-3">
                  <ResponsiveImage
                    src={selectedProduct.image}
                    alt={selectedProduct.name}
                    loading="lazy"
                    className="w-full h-full object-contain"
                    sizes="(max-width:1024px) 100vw, 50vw"
                  />
                  {selectedProduct.stock <= 5 && (
                    <div className="absolute top-3 right-3 px-2 py-1 bg-gradient-to-r from-[#C5A021] to-red-500 rounded-full">
                      <span className="font-outfit text-[10px] font-bold text-[#0A0604] whitespace-nowrap">
                        Only {selectedProduct.stock} left
                      </span>
                    </div>
                  )}
                </div>

                {/* Product Info */}
                <h2 className="font-syncopate text-lg text-cream mb-1">{selectedProduct.name}</h2>
                <p className="font-outfit text-xs text-cream/70 mb-2">Premium merchandise item</p>

                <div className="flex items-center gap-2 mb-3">
                  <i className="ri-star-fill text-yellow-400 text-sm"></i>
                  <span className="font-outfit text-xs text-cream">4.5</span>
                  <span className="font-outfit text-[10px] text-cream/60">(120 reviews)</span>
                </div>

                <div className="mb-3">
                  <h3 className="font-syncopate text-[10px] text-cream mb-2">PRICE</h3>
                  <p className="text-2xl font-bold text-gold font-outfit">₹{selectedProduct.price}</p>
                  {selectedProduct.stock <= 5 && (
                    <p className="text-xs text-red-400 mt-1 font-outfit">Only {selectedProduct.stock} left in stock</p>
                  )}
                </div>

                {/* Size Selection */}
                {selectedProduct.variants.sizes.length > 0 && (
                  <div className="mb-3">
                    <h3 className="font-syncopate text-[10px] text-cream mb-2">SIZE</h3>
                    <div className="flex flex-wrap gap-2">
                      {selectedProduct.variants.sizes.map((size) => (
                        <motion.button
                          key={size}
                          onClick={() => setSelectedVariant({ ...selectedVariant, size })}
                          className={`py-2 px-4 rounded-lg font-outfit cursor-pointer whitespace-nowrap transition-all ${selectedVariant.size === size
                            ? 'bg-gradient-to-r from-gold to-gold-light text-obsidian font-bold'
                            : 'bg-cocoa-dark/50 text-cream border border-gold/20 hover:border-gold/50'
                            }`}
                          whileHover={{ scale: 1.05 }}
                          whileTap={{ scale: 0.95 }}
                        >
                          <div className="text-xs font-bold">{size}</div>
                        </motion.button>
                      ))}
                    </div>
                  </div>
                )}

                {/* Color Selection */}
                {selectedProduct.variants.colors.length > 0 && (
                  <div className="mb-3">
                    <h3 className="font-syncopate text-[10px] text-cream mb-2">COLOR</h3>
                    <div className="flex flex-wrap gap-2">
                      {selectedProduct.variants.colors.map((color) => (
                        <motion.button
                          key={color}
                          onClick={() => setSelectedVariant({ ...selectedVariant, color })}
                          className={`py-2 px-4 rounded-lg font-outfit cursor-pointer whitespace-nowrap transition-all ${selectedVariant.color === color
                            ? 'bg-gradient-to-r from-gold to-gold-light text-obsidian font-bold'
                            : 'bg-cocoa-dark/50 text-cream border border-gold/20 hover:border-gold/50'
                            }`}
                          whileHover={{ scale: 1.05 }}
                          whileTap={{ scale: 0.95 }}
                        >
                          <div className="text-xs font-bold">{color}</div>
                        </motion.button>
                      ))}
                    </div>
                  </div>
                )}

                {/* Quantity */}
                <div className="mb-3">
                  <h3 className="font-syncopate text-[10px] text-cream mb-2">QUANTITY</h3>
                  <div className="flex items-center gap-3">
                    <motion.button
                      onClick={() => setQuantity(Math.max(1, quantity - 1))}
                      className="w-8 h-8 rounded-full bg-cocoa-dark border border-gold/20 flex items-center justify-center cursor-pointer hover:border-gold"
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.9 }}
                    >
                      <i className="ri-subtract-line text-gold text-sm"></i>
                    </motion.button>
                    <span className="font-syncopate text-lg text-cream w-10 text-center">{quantity}</span>
                    <motion.button
                      onClick={() => setQuantity(quantity + 1)}
                      className="w-8 h-8 rounded-full bg-cocoa-dark border border-gold/20 flex items-center justify-center cursor-pointer hover:border-gold"
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.9 }}
                    >
                      <i className="ri-add-line text-gold text-sm"></i>
                    </motion.button>
                  </div>
                </div>
              </div>

              {/* Sticky Footer */}
              <div className="border-t border-gold/20 px-6 py-3 bg-cocoa/95 backdrop-blur-sm">
                <div className="flex items-center gap-3">
                  <motion.button
                    onClick={() => toggleWishlist(selectedProduct)}
                    className="w-10 h-10 rounded-full border border-gold/20 flex items-center justify-center cursor-pointer hover:bg-gold/10 flex-shrink-0"
                    whileHover={{ scale: 1.1 }}
                    whileTap={{ scale: 0.9 }}
                  >
                    <i className={`${isInWishlist(selectedProduct.id) ? 'ri-heart-fill' : 'ri-heart-line'} text-gold text-lg`}></i>
                  </motion.button>

                  <motion.button
                    onClick={() => {
                      addToCart({ ...selectedProduct, variant: selectedVariant, quantity });
                      setSelectedProduct(null);
                    }}
                    className="flex-1 py-2.5 bg-gradient-to-r from-gold to-gold-light text-obsidian font-syncopate font-bold text-xs tracking-wider rounded-full cursor-pointer whitespace-nowrap flex items-center justify-center gap-2"
                    whileHover={{ scale: 1.02, boxShadow: '0 0 40px rgba(197, 160, 33, 0.6)' }}
                    whileTap={{ scale: 0.98 }}
                  >
                    <i className="ri-shopping-cart-line"></i>
                    ADD TO CART
                  </motion.button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </section>
  );
}
