import { motion } from 'framer-motion';
import { useState } from 'react';
import ResponsiveImage from '../../../components/ResponsiveImage';

export default function Footer() {
  const [email, setEmail] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Newsletter signup:', email);
    setEmail('');
  };

  return (
    <footer className="relative bg-[#C5A021] text-[#140B07] py-20 px-4 md:px-8">
      <div className="max-w-7xl mx-auto">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-12 mb-16">
          <div>
            <div className="h-12 w-auto mb-6 brightness-0">
              <ResponsiveImage src="logo.png" alt="The Chocolate Room" className="h-12 w-auto" sizes="120px" />
            </div>
            <p className="text-sm text-[#140B07]/80 leading-relaxed mb-6">
              Crafting moments of indulgence since 2024. Where passion meets perfection in every bite.
            </p>
            <div className="flex gap-4">
              {['ri-facebook-fill', 'ri-instagram-line', 'ri-twitter-x-line', 'ri-youtube-fill'].map((icon) => (
                <motion.a
                  key={icon}
                  href="#"
                  className="w-10 h-10 bg-[#140B07]/10 rounded-full flex items-center justify-center cursor-pointer"
                  whileHover={{ scale: 1.1, backgroundColor: 'rgba(20, 11, 7, 0.2)' }}
                  whileTap={{ scale: 0.95 }}
                >
                  <i className={`${icon} text-lg text-[#140B07]`}></i>
                </motion.a>
              ))}
            </div>
          </div>

          <div>
            <h4 className="text-lg font-semibold mb-6">Quick Links</h4>
            <ul className="space-y-3">
              {['Menu', 'Merchandise', 'Gift Cards', 'Loyalty Program', 'Store Locator', 'About Us'].map((link) => (
                <li key={link}>
                  <a href="#" className="text-sm text-[#140B07]/80 hover:text-[#140B07] transition-colors">
                    {link}
                  </a>
                </li>
              ))}
            </ul>
          </div>

          <div>
            <h4 className="text-lg font-semibold mb-6">Support</h4>
            <ul className="space-y-3">
              {['Contact Us', 'FAQs', 'Franchise Inquiry', 'Careers', 'Terms & Conditions', 'Privacy Policy'].map((link) => (
                <li key={link}>
                  <a href="#" className="text-sm text-[#140B07]/80 hover:text-[#140B07] transition-colors">
                    {link}
                  </a>
                </li>
              ))}
            </ul>
          </div>

          <div>
            <h4 className="text-lg font-semibold mb-6">Newsletter</h4>
            <p className="text-sm text-[#140B07]/80 mb-4">
              Subscribe for exclusive offers and updates
            </p>
            <form onSubmit={handleSubmit} className="space-y-3">
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder="Your email address"
                required
                className="w-full px-4 py-3 bg-[#140B07]/10 border border-[#140B07]/20 rounded-xl text-sm text-[#140B07] placeholder-[#140B07]/50 focus:outline-none focus:border-[#140B07]"
              />
              <motion.button
                type="submit"
                className="w-full py-3 bg-[#140B07] text-[#C5A021] rounded-xl font-semibold text-sm cursor-pointer whitespace-nowrap"
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
              >
                Subscribe
              </motion.button>
            </form>
          </div>
        </div>

        <div className="pt-8 border-t border-[#140B07]/20">
          <div className="flex flex-col md:flex-row justify-between items-center gap-4">
            <p className="text-sm text-[#140B07]/70">
              © 2024 The Chocolate Room. All rights reserved. | GST: 07AABCT1234F1Z5
            </p>
            <a
              href="https://marwiztech.com/"
              target="_blank"
              rel="noopener noreferrer"
              className="text-sm text-[#140B07]/70 hover:text-[#140B07] transition-colors"
            >
              Powered by Marwiz
            </a>
          </div>
        </div>
      </div>
    </footer>
  );
}
