import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useWishlist } from '../../../context/WishlistContext';



export default function SmartMenu({ orderType, setOrderType, addToCart }) {
  const [showProductModal, setShowProductModal] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [selectedSize, setSelectedSize] = useState('regular');
  const [quantity, setQuantity] = useState(1);
  const { toggleWishlist, isInWishlist } = useWishlist();


  const allMenuItems = [
    { id: 'hc1', name: 'Signature Dark Hot Chocolate', price: 280, image: '/images/optimized/img-e3970fea16e0-640.webp', veg: true, bestseller: true, category: 'hot-chocolate', festive: false },
    { id: 'hc2', name: 'White Chocolate Dream', price: 260, image: '/images/optimized/img-786a3a879f58-640.webp', veg: true, bestseller: false, category: 'hot-chocolate', festive: false },
    { id: 'hc3', name: 'Hazelnut Praline Delight', price: 320, image: '/images/optimized/img-da051a87667e-640.webp', veg: true, bestseller: true, category: 'hot-chocolate', festive: false },
    { id: 'hc4', name: 'Mint Chocolate Fusion', price: 290, image: '/images/optimized/img-78aacd333a08-640.webp', veg: true, bestseller: false, category: 'hot-chocolate', festive: true },
    { id: 'd1', name: 'Triple Chocolate Brownie', price: 240, image: '/images/optimized/img-d066dfe47fd3-640.webp', veg: true, bestseller: true, category: 'desserts', festive: false },
    { id: 'd2', name: 'Molten Lava Cake', price: 280, image: '/images/optimized/img-d2bfaa1fb666-640.webp', veg: true, bestseller: true, category: 'desserts', festive: false },
    { id: 'd3', name: 'Tiramisu Classic', price: 260, image: '/images/optimized/img-d88ba7ac37ad-640.webp', veg: true, bestseller: false, category: 'desserts', festive: true },
    { id: 'b1', name: 'Cold Brew Coffee', price: 180, image: '/images/optimized/img-f1529b926e75-640.webp', veg: true, bestseller: false, category: 'beverages', festive: false },
    { id: 'b2', name: 'Chocolate Frappe', price: 220, image: '/images/optimized/img-eb7dcc0902e5-640.webp', veg: true, bestseller: true, category: 'beverages', festive: false },
    { id: 's1', name: 'TCR Signature Cookie', price: 120, image: '/images/optimized/img-04f093678b23-640.webp', veg: true, bestseller: true, category: 'snacks', festive: false },
    { id: 's2', name: 'Chocolate Croissant', price: 160, image: '/images/optimized/img-34b3b4f5dcd0-640.webp', veg: true, bestseller: false, category: 'snacks', festive: true }
  ];

  const bestSellers = allMenuItems.filter(item => item.bestseller);
  const festiveOffers = allMenuItems.filter(item => item.festive);
  const pastReorders = allMenuItems.slice(0, 4);

  const handleProductClick = (product) => {
    setSelectedProduct(product);
    setSelectedSize('regular');
    setQuantity(1);
    setShowProductModal(true);
  };

  const handleAddToCart = () => {
    if (!selectedProduct) return;

    const sizes = [
      { id: 'regular', name: 'Regular', price: selectedProduct.price },
      { id: 'large', name: 'Large', price: Math.round(selectedProduct.price * 1.3) },
      { id: 'jumbo', name: 'Jumbo', price: Math.round(selectedProduct.price * 1.6) }
    ];

    const currentPrice = sizes.find(s => s.id === selectedSize)?.price || selectedProduct.price;

    const cartItem = {
      id: selectedProduct.id,
      name: selectedProduct.name,
      price: currentPrice,
      size: selectedSize,
      quantity: quantity,
      image: selectedProduct.image
    };

    addToCart(cartItem);
    setShowProductModal(false);
  };

  const sizes = selectedProduct ? [
    { id: 'regular', name: 'Regular', price: selectedProduct.price },
    { id: 'large', name: 'Large', price: Math.round(selectedProduct.price * 1.3) },
    { id: 'jumbo', name: 'Jumbo', price: Math.round(selectedProduct.price * 1.6) }
  ] : [];

  const currentPrice = sizes.find(s => s.id === selectedSize)?.price || 0;
  const totalPrice = currentPrice * quantity;

  const ProductCard = ({ item }) => (
    <motion.div
      className="group relative glass-panel rounded-2xl overflow-hidden cursor-pointer border border-gold/10 hover:border-gold/40 transition-all flex-shrink-0 w-72"
      onClick={() => handleProductClick(item)}
      whileHover={{ y: -6, boxShadow: '0 15px 30px rgba(197, 160, 33, 0.3)' }}
    >
      <div className="absolute top-3 left-3 z-10 w-5 h-5 border-2 border-green-500 rounded flex items-center justify-center bg-obsidian/80 backdrop-blur-sm">
        <div className="w-2.5 h-2.5 rounded-full bg-green-500"></div>
      </div>

      {item.bestseller && (
        <div className="absolute top-3 right-3 z-10 px-2 py-1 bg-gradient-to-r from-gold to-gold-light rounded-full gold-shimmer-effect">
          <span className="font-outfit text-[10px] font-bold text-obsidian whitespace-nowrap">
            ⭐ BEST SELLER
          </span>
        </div>
      )}

      <div className="relative w-full h-48 overflow-hidden">
        <img
          src={item.image}
          alt={item.name}
          className="w-full h-full object-cover object-top group-hover:scale-110 transition-transform duration-500"
        />
        <div className="absolute inset-0 bg-gradient-to-t from-cocoa via-transparent to-transparent opacity-60"></div>
      </div>

      <div className="p-4">
        <h3 className="font-syncopate text-sm text-cream leading-tight mb-2">
          {item.name}
        </h3>

        <div className="flex items-center justify-between mb-3">
          <span className="font-syncopate text-lg text-gold font-bold">
            ₹{item.price}
          </span>
          <div className="flex items-center gap-1">
            <i className="ri-star-fill text-yellow-400 text-xs"></i>
            <span className="font-outfit text-xs text-cream/80">4.5</span>
          </div>
        </div>

        <motion.button
          className="w-full py-2 bg-gradient-to-r from-gold to-gold-light text-obsidian font-syncopate font-bold text-[10px] tracking-wider rounded-full cursor-pointer whitespace-nowrap"
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.98 }}
          onClick={(e) => {
            e.stopPropagation();
            handleProductClick(item);
          }}
        >
          ADD TO CART
        </motion.button>
      </div>
    </motion.div>
  );

  return (
    <section id="smart-menu" className="relative py-32 px-4 md:px-8">
      <div className="max-w-[1920px] mx-auto">
        <motion.div
          className="text-center mb-16"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
        >
          <h2 className="text-3xl sm:text-5xl md:text-6xl font-syncopate text-gold mb-4">Smart Menu</h2>
          <p className="text-lg text-cream/70 font-outfit">Crafted for chocolate lovers</p>
        </motion.div>

        {/* Horizontal Category Ribbon */}


        {/* Best Sellers Section */}
        <motion.div
          className="mb-16"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
        >
          <div className="flex items-center justify-between mb-6">
            <h3 className="font-syncopate text-2xl text-cream">Best Sellers</h3>
            <motion.button
              onClick={() => window.REACT_APP_NAVIGATE && window.REACT_APP_NAVIGATE('/menu')}
              className="text-gold font-outfit text-sm hover:underline cursor-pointer whitespace-nowrap"
              whileHover={{ x: 5 }}
            >
              View All <i className="ri-arrow-right-line ml-1"></i>
            </motion.button>
          </div>

          <div className="flex gap-6 overflow-x-auto pb-4 scrollbar-hide">
            {bestSellers.map((item) => (
              <ProductCard key={item.id} item={item} />
            ))}
          </div>
        </motion.div>

        {/* Past Re-orders Section */}
        <motion.div
          className="mb-16"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
        >
          <div className="flex items-center justify-between mb-6">
            <h3 className="font-syncopate text-2xl text-cream">Past Re-orders</h3>
            <motion.button
              onClick={() => window.REACT_APP_NAVIGATE && window.REACT_APP_NAVIGATE('/account')}
              className="text-gold font-outfit text-sm hover:underline cursor-pointer whitespace-nowrap"
              whileHover={{ x: 5 }}
            >
              View History <i className="ri-arrow-right-line ml-1"></i>
            </motion.button>
          </div>

          <div className="flex gap-6 overflow-x-auto pb-4 scrollbar-hide">
            {pastReorders.map((item) => (
              <ProductCard key={item.id} item={item} />
            ))}
          </div>
        </motion.div>

        {/* Festive Offers Section */}
        <motion.div
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
        >
          <div className="flex items-center justify-between mb-6">
            <h3 className="font-syncopate text-2xl text-cream">Festive Offers</h3>
            <span className="px-4 py-2 bg-gold/20 border border-gold rounded-full text-gold font-outfit text-xs font-bold whitespace-nowrap">
              🎉 LIMITED TIME
            </span>
          </div>

          <div className="flex gap-6 overflow-x-auto pb-4 scrollbar-hide">
            {festiveOffers.map((item) => (
              <ProductCard key={item.id} item={item} />
            ))}
          </div>
        </motion.div>
      </div>

      {/* Product Detail Modal */}
      <AnimatePresence>
        {showProductModal && selectedProduct && (
          <motion.div
            className="fixed inset-0 bg-black/80 backdrop-blur-sm z-[1000] flex items-center justify-center p-4"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setShowProductModal(false)}
          >
            <motion.div
              className="glass-panel-strong rounded-2xl border-2 border-gold max-w-md w-full max-h-[85vh] overflow-hidden flex flex-col"
              initial={{ scale: 0.8, y: 50 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.8, y: 50 }}
              onClick={(e) => e.stopPropagation()}
            >
              {/* Close Button */}
              <div className="absolute top-3 right-3 z-10">
                <motion.button
                  onClick={() => setShowProductModal(false)}
                  className="w-8 h-8 rounded-full bg-cocoa-dark/80 border border-gold/20 flex items-center justify-center cursor-pointer hover:border-gold"
                  whileHover={{ scale: 1.1, rotate: 90 }}
                  whileTap={{ scale: 0.9 }}
                >
                  <i className="ri-close-line text-cream text-lg"></i>
                </motion.button>
              </div>

              {/* Scrollable Content Area */}
              <div className="flex-1 overflow-y-auto px-6 pt-6 pb-4">
                {/* Product Image - Full View with Contain */}
                <div className="relative w-full h-48 rounded-xl overflow-hidden mb-3">
                  <img
                    src={selectedProduct.image}
                    alt={selectedProduct.name}
                    className="w-full h-full object-contain"
                  />
                  {/* Best Seller tag removed */}
                </div>

                {/* Product Info - Compact */}
                <h2 className="font-syncopate text-lg text-cream mb-1">{selectedProduct.name}</h2>
                <p className="font-outfit text-xs text-cream/70 mb-2">Rich and indulgent chocolate experience</p>

                <div className="flex items-center gap-2 mb-3">
                  <i className="ri-star-fill text-yellow-400 text-sm"></i>
                  <span className="font-outfit text-xs text-cream">4.5</span>
                  <span className="font-outfit text-[10px] text-cream/60">(120 reviews)</span>
                </div>

                {/* Size Selection - Compact */}
                <div className="mb-3">
                  <h3 className="font-syncopate text-[10px] text-cream mb-2">SELECT SIZE</h3>
                  <div className="grid grid-cols-3 gap-2">
                    {sizes.map((size) => (
                      <motion.button
                        key={size.id}
                        onClick={() => setSelectedSize(size.id)}
                        className={`py-2 px-2 rounded-lg font-outfit cursor-pointer whitespace-nowrap transition-all ${selectedSize === size.id
                          ? 'bg-gradient-to-r from-gold to-gold-light text-obsidian font-bold'
                          : 'bg-cocoa-dark/50 text-cream border border-gold/20 hover:border-gold/50'
                          }`}
                        whileHover={{ scale: 1.05 }}
                        whileTap={{ scale: 0.95 }}
                      >
                        <div className="text-xs font-bold tracking-wide">{size.name}</div>
                        <div className="text-[11px] font-medium mt-0.5 opacity-90">₹{size.price}</div>
                      </motion.button>
                    ))}
                  </div>
                </div>

                {/* Quantity - Compact */}
                <div className="mb-3">
                  <h3 className="font-syncopate text-[10px] text-cream mb-2">QUANTITY</h3>
                  <div className="flex items-center gap-3">
                    <motion.button
                      onClick={() => setQuantity(Math.max(1, quantity - 1))}
                      className="w-8 h-8 rounded-full bg-cocoa-dark border border-gold/20 flex items-center justify-center cursor-pointer hover:border-gold"
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.9 }}
                    >
                      <i className="ri-subtract-line text-gold text-sm"></i>
                    </motion.button>
                    <span className="font-syncopate text-lg text-cream w-10 text-center">{quantity}</span>
                    <motion.button
                      onClick={() => setQuantity(quantity + 1)}
                      className="w-8 h-8 rounded-full bg-cocoa-dark border border-gold/20 flex items-center justify-center cursor-pointer hover:border-gold"
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.9 }}
                    >
                      <i className="ri-add-line text-gold text-sm"></i>
                    </motion.button>
                  </div>
                </div>
              </div>

              {/* Sticky Footer - Always Visible */}
              <div className="border-t border-gold/20 px-6 py-3 bg-cocoa/95 backdrop-blur-sm">
                <div className="flex items-center gap-3">
                  <motion.button
                    onClick={() => toggleWishlist(selectedProduct)}
                    className="w-10 h-10 rounded-full border border-gold/20 flex items-center justify-center cursor-pointer hover:bg-gold/10 flex-shrink-0"
                    whileHover={{ scale: 1.1 }}
                    whileTap={{ scale: 0.9 }}
                  >
                    <i className={`${isInWishlist(selectedProduct.id) ? 'ri-heart-fill' : 'ri-heart-line'} text-gold text-lg`}></i>
                  </motion.button>

                  <motion.button
                    onClick={handleAddToCart}
                    className="flex-1 py-2.5 bg-gradient-to-r from-gold to-gold-light text-obsidian font-syncopate font-bold text-xs tracking-wider rounded-full cursor-pointer whitespace-nowrap flex items-center justify-center gap-2"
                    whileHover={{ scale: 1.02, boxShadow: '0 0 40px rgba(197, 160, 33, 0.6)' }}
                    whileTap={{ scale: 0.98 }}
                  >
                    <i className="ri-shopping-cart-line"></i>
                    ADD ₹{totalPrice}
                  </motion.button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </section>
  );
}
