
import { motion, useMotionValue, useTransform } from 'framer-motion';
import { useState, useMemo, useRef } from 'react';
import { commonShadow } from '../../../utils/uiEffects';
import { rafThrottle } from '../../../utils/animationUtils';

export default function LoyaltyWallet() {
  const [showQR, setShowQR] = useState(false);
  const cardRef = useRef(null);
  const rotateX = useMotionValue(0);
  const rotateY = useMotionValue(0);

  const handleMouseMoveRaw = (e) => {
    if (!cardRef.current) return;
    const rect = cardRef.current.getBoundingClientRect();
    const centerX = rect.left + rect.width / 2;
    const centerY = rect.top + rect.height / 2;
    const rotateXValue = (e.clientY - centerY) / 20;
    const rotateYValue = (centerX - e.clientX) / 20;
    rotateX.set(rotateXValue);
    rotateY.set(rotateYValue);
  };

  // throttle pointer updates to rAF for cheaper main-thread work
  const handleMouseMove = useMemo(() => rafThrottle(handleMouseMoveRaw), [handleMouseMoveRaw]);

  const handleMouseLeave = () => {
    rotateX.set(0);
    rotateY.set(0);
  };

  return (
    <section id="loyalty" className="relative py-16 px-4 md:px-8">
      <div className="max-w-7xl mx-auto">
        <motion.div
          className="text-center mb-16"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
        >
          <h2 className="text-3xl md:text-4xl font-serif text-[#C5A021] mb-3">The Gold Card</h2>
          <p className="text-lg text-[#F8F4F0]/70 font-light">Your digital passport to indulgence</p>
        </motion.div>

        <div className="grid md:grid-cols-2 gap-16 items-center">
          <motion.div
            ref={cardRef}
            className="relative perspective-1000"
            onMouseMove={handleMouseMove}
            onMouseLeave={handleMouseLeave}
            initial={{ opacity: 0, x: -50 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.8 }}
          >
            <motion.div
              className={`relative w-full aspect-[1.6/1] bg-gradient-to-br from-[#C5A021] via-[#F8F4F0] to-[#C5A021] rounded-3xl p-8 shadow-2xl ${commonShadow}`}
              style={{
                rotateX,
                rotateY,
                transformStyle: 'preserve-3d'
              }}
            >
              <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,')] opacity-30 rounded-3xl"></div>

              <div className="relative z-10 h-full flex flex-col justify-between">
                <div className="flex justify-between items-start">
                  <div>
                    <h3 className="text-2xl font-bold text-[#140B07] mb-1">TCR Gold</h3>
                    <p className="text-sm text-[#140B07]/70">Member Since 2024</p>
                  </div>
                  <motion.div
                    className="w-12 h-12 bg-[#140B07]/10 rounded-full flex items-center justify-center"
                    animate={{ rotate: 360 }}
                    transition={{ duration: 20, repeat: Infinity, ease: 'linear' }}
                  >
                    <i className="ri-vip-crown-line text-2xl text-[#140B07]"></i>
                  </motion.div>
                </div>

                <div>
                  <p className="text-sm text-[#140B07]/70 mb-2">Available Points</p>
                  <h4 className="text-5xl font-bold text-[#140B07] mb-4">2,450</h4>
                  <div className="w-full h-2 bg-[#140B07]/20 rounded-full overflow-hidden">
                    <motion.div
                      className="h-full bg-[#140B07]"
                      initial={{ width: 0 }}
                      whileInView={{ width: '65%' }}
                      viewport={{ once: true }}
                      transition={{ duration: 1.5, delay: 0.5 }}
                    />
                  </div>
                  <p className="text-xs text-[#140B07]/70 mt-2">550 points to next reward</p>
                </div>

                <div className="flex justify-between items-center">
                  <div>
                    <p className="text-xs text-[#140B07]/70">Card Number</p>
                    <p className="text-sm font-mono text-[#140B07]">**** **** **** 8742</p>
                  </div>
                  <motion.button
                    onClick={() => setShowQR(!showQR)}
                    className="px-6 py-2 bg-[#140B07] text-[#C5A021] rounded-full text-sm font-semibold cursor-pointer whitespace-nowrap"
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                  >
                    Scan to Pay
                  </motion.button>
                </div>
              </div>
            </motion.div>
          </motion.div>

          <motion.div
            className="space-y-8"
            initial={{ opacity: 0, x: 50 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.8 }}
          >
            <div className="bg-[#25160F]/50 backdrop-blur-md rounded-2xl p-8 border border-[#C5A021]/15">
              <div className="flex items-center gap-4 mb-4">
                <div className="w-12 h-12 bg-[#C5A021]/20 rounded-full flex items-center justify-center">
                  <i className="ri-gift-line text-2xl text-[#C5A021]"></i>
                </div>
                <div>
                  <h4 className="text-xl font-semibold text-[#F8F4F0]">Rewards Unlocked</h4>
                  <p className="text-sm text-[#F8F4F0]/60">3 treats waiting for you</p>
                </div>
              </div>
              <div className="space-y-3">
                <div className="flex items-center justify-between p-3 bg-[#140B07]/30 rounded-lg">
                  <span className="text-sm text-[#F8F4F0]">Free Hot Chocolate</span>
                  <span className="text-xs text-[#C5A021] font-semibold">AVAILABLE</span>
                </div>
                <div className="flex items-center justify-between p-3 bg-[#140B07]/30 rounded-lg">
                  <span className="text-sm text-[#F8F4F0]">20% Off Desserts</span>
                  <span className="text-xs text-[#C5A021] font-semibold">AVAILABLE</span>
                </div>
                <div className="flex items-center justify-between p-3 bg-[#140B07]/30 rounded-lg">
                  <span className="text-sm text-[#F8F4F0]">Birthday Special</span>
                  <span className="text-xs text-[#C5A021] font-semibold">AVAILABLE</span>
                </div>
              </div>
            </div>

            <div className="bg-[#25160F]/50 backdrop-blur-md rounded-2xl p-8 border border-[#C5A021]/15">
              <h4 className="text-xl font-semibold text-[#F8F4F0] mb-4">How It Works</h4>
              <div className="space-y-4">
                <div className="flex gap-4">
                  <div className="w-8 h-8 bg-[#C5A021] rounded-full flex items-center justify-center flex-shrink-0">
                    <span className="text-sm font-bold text-[#140B07]">1</span>
                  </div>
                  <div>
                    <p className="text-sm text-[#F8F4F0]">Earn 10 points for every ₹100 spent</p>
                  </div>
                </div>
                <div className="flex gap-4">
                  <div className="w-8 h-8 bg-[#C5A021] rounded-full flex items-center justify-center flex-shrink-0">
                    <span className="text-sm font-bold text-[#140B07]">2</span>
                  </div>
                  <div>
                    <p className="text-sm text-[#F8F4F0]">Redeem points for exclusive rewards</p>
                  </div>
                </div>
                <div className="flex gap-4">
                  <div className="w-8 h-8 bg-[#C5A021] rounded-full flex items-center justify-center flex-shrink-0">
                    <span className="text-sm font-bold text-[#140B07]">3</span>
                  </div>
                  <div>
                    <p className="text-sm text-[#F8F4F0]">Get birthday treats and special offers</p>
                  </div>
                </div>
              </div>
            </div>
          </motion.div>
        </div>
      </div>
    </section>
  );
}
