/* Small animation utilities for performance-conscious interactions.
   - rafThrottle: throttle callbacks using requestAnimationFrame
   - useParallax: small hook to attach lightweight parallax to an element (no framer-motion)
   - applyWillChangeTemporarily: helper to add/remove will-change on interaction
*/

export function rafThrottle(fn) {
    let raf = 0;
    let lastArgs = null;
    return function throttled(...args) {
        lastArgs = args;
        if (!raf) {
            raf = requestAnimationFrame(() => {
                raf = 0;
                if (lastArgs) fn(...lastArgs);
                lastArgs = null;
            });
        }
    };
}

export function applyWillChangeTemporarily(el, props = 'transform, opacity') {
    if (!el) return () => { };
    const prev = el.style.willChange;
    el.style.willChange = props;
    const cleanup = () => {
        try {
            el.style.willChange = prev || 'auto';
        } catch {
            /* noop */
        }
    };
    return cleanup;
}

export function useParallax(options) {
    // returns: attach(ref) -> cleanup
    const strength = options?.strength ?? 0.12;
    const threshold = options?.threshold ?? 0.1;

    return function attach(el) {
        if (!el || typeof window === 'undefined') return () => { };
        let mounted = true;
        let bboxTop = 0;
        const onFrame = rafThrottle(() => {
            if (!mounted) return;
            const rect = el.getBoundingClientRect();
            const midpoint = rect.top + rect.height / 2 - window.innerHeight / 2;
            const delta = midpoint / (window.innerHeight / 2);
            const translateY = Math.max(-1, Math.min(1, delta)) * 100 * strength;
            el.style.transform = `translate3d(0, ${translateY}px, 0)`;
        });

        const io = new IntersectionObserver((entries) => {
            for (const e of entries) {
                if (!mounted) return;
                if (e.isIntersecting) {
                    // start listening
                    window.addEventListener('scroll', onFrame, { passive: true });
                    onFrame();
                } else {
                    window.removeEventListener('scroll', onFrame);
                    // reset transform when out of view
                    el.style.transform = '';
                }
            }
        }, { threshold });

        io.observe(el);

        return () => {
            mounted = false;
            io.disconnect();
            window.removeEventListener('scroll', onFrame);
            el.style.transform = '';
        };
    };
}
