
import { motion } from 'framer-motion';
import Animated from '../../../components/Animated';
import ResponsiveImage from '../../../components/ResponsiveImage';

export default function SocialWall() {
  const testimonials = [
    { id: 1, name: 'Priya Sharma', location: 'Connaught Place', rating: 5, text: 'The best hot chocolate I have ever had! The ambiance is perfect for a cozy evening.', image: '/images/optimized/img-e019cd741d6f-640.webp' },
    { id: 2, name: 'Rahul Verma', location: 'Cyber Hub', rating: 5, text: 'Their desserts are to die for! The molten lava cake is absolutely divine.', image: '/images/optimized/img-92f0edde9e52-640.webp' },
    { id: 3, name: 'Ananya Kapoor', location: 'Khan Market', rating: 5, text: 'Love the loyalty program! The rewards are amazing and the staff is so friendly.', image: '/images/optimized/img-5f55966da016-640.webp' },
    { id: 4, name: 'Vikram Singh', location: 'Saket', rating: 5, text: 'Perfect place for a date night. The chocolate fondue is a must-try!', image: '/images/optimized/img-d0ad31a04f1e-640.webp' },
    { id: 5, name: 'Neha Gupta', location: 'Connaught Place', rating: 5, text: 'The merchandise is so cute! I bought the TCR mug and I use it every day.', image: '/images/optimized/img-af7fb68f095c-640.webp' },
    { id: 6, name: 'Arjun Malhotra', location: 'Cyber Hub', rating: 5, text: 'Great coffee and even better chocolate! This is my go-to spot for meetings.', image: '/images/optimized/img-ac5f8885dcbc-640.webp' }
  ];

  const instagramPosts = [
    { id: 1, image: '/images/optimized/img-c3ffac074626-640.webp', likes: 2847 },
    { id: 2, image: '/images/optimized/img-bc3bedceda1f-640.webp', likes: 3521 },
    { id: 3, image: '/images/optimized/img-4e6eecf806ba-640.webp', likes: 1923 },
    { id: 4, image: '/images/optimized/img-7ccc0982ae65-640.webp', likes: 4156 },
    { id: 5, image: '/images/optimized/img-838f734a2113-640.webp', likes: 2634 },
    { id: 6, image: '/images/optimized/img-7a1f5ef9c11b-640.webp', likes: 3892 }
  ];

  return (
    <section className="relative py-16 px-4 md:px-8 bg-[#25160F]/30">
      <div className="max-w-7xl mx-auto">
        <motion.div
          className="text-center mb-16"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
        >
          <h2 className="text-3xl md:text-4xl font-serif text-[#C5A021] mb-3">What People Say</h2>
          <p className="text-lg text-[#F8F4F0]/70 font-light">Real experiences from our chocolate lovers</p>
        </motion.div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-24">
          {testimonials.map((testimonial, index) => (
            <Animated
              key={testimonial.id}
              className="bg-[#25160F]/50 backdrop-blur-md rounded-3xl p-6 border border-[#C5A021]/15"
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: index * 0.1 }}
              whileHover={{ translateY: -5, scale: 1.01 }}
              promoteOnHover
            >
              <div className="flex items-center gap-4 mb-4">
                <div className="w-12 h-12 rounded-full overflow-hidden">
                  <ResponsiveImage src={testimonial.image} alt={testimonial.name} className="w-full h-full object-cover object-top" sizes="48px" />
                </div>
                <div>
                  <h4 className="text-[#F8F4F0] font-semibold">{testimonial.name}</h4>
                  <p className="text-xs text-[#F8F4F0]/60">{testimonial.location}</p>
                </div>
              </div>
              <div className="flex gap-1 mb-3">
                {[...Array(testimonial.rating)].map((_, i) => (
                  <i key={i} className="ri-star-fill text-[#C5A021] text-sm"></i>
                ))}
              </div>
              <p className="text-sm text-[#F8F4F0]/80 leading-relaxed">{testimonial.text}</p>
            </Animated>
          ))}
        </div>

        <motion.div
          className="text-center mb-12"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
        >
          <h3 className="text-4xl font-serif text-[#C5A021] mb-4">Follow Us on Instagram</h3>
          <p className="text-[#F8F4F0]/70">@thechocolateroom</p>
        </motion.div>

        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
          {instagramPosts.map((post, index) => (
            <Animated
              key={post.id}
              className="relative aspect-square rounded-2xl overflow-hidden group cursor-pointer"
              initial={{ opacity: 0, scale: 0.9 }}
              whileInView={{ opacity: 1, scale: 1 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: index * 0.05 }}
              whileHover={{ scale: 1.03 }}
              promoteOnHover
            >
              <ResponsiveImage src={post.image} alt={`Instagram post ${post.id}`} className="w-full h-full object-cover object-top" sizes="(max-width: 640px) 100vw, 16vw" />
              <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                <div className="flex items-center gap-2 text-white">
                  <i className="ri-heart-fill text-2xl"></i>
                  <span className="font-semibold">{post.likes.toLocaleString()}</span>
                </div>
              </div>
            </Animated>
          ))} 
        </div>
      </div>
    </section>
  );
}
