import { useState, useEffect } from 'react';
import { useCart } from '../../context/CartContext';
import Hero from './components/Hero';
import SmartMenu from './components/SmartMenu';
import LoyaltyWallet from './components/LoyaltyWallet';
import Merchandise from './components/Merchandise';
import TheCraft from './components/TheCraft';
import SocialWall from './components/SocialWall';
import Footer from './components/Footer';

export default function Home() {
  const { addToCart } = useCart();
  const [orderType, setOrderType] = useState('dine-in');

  // Handle hash scrolling
  useEffect(() => {
    if (window.location.hash) {
      const id = window.location.hash.replace('#', '');
      const element = document.getElementById(id);
      if (element) {
        // Slight delay to ensure layout is settled
        setTimeout(() => {
          element.scrollIntoView({ behavior: 'smooth' });
        }, 100);
      }
    }
  }, []);

  return (
    <div className="relative bg-[#140B07] text-[#F8F4F0] overflow-x-hidden">
      <Hero />
      <SmartMenu orderType={orderType} setOrderType={setOrderType} addToCart={addToCart} />
      <Merchandise />
      <LoyaltyWallet />
      <TheCraft />
      <SocialWall />
      <Footer />
    </div>
  );
}
