
import { motion } from 'framer-motion';
import { useRef, useEffect } from 'react';
import ResponsiveImage from '../../../components/ResponsiveImage';
import { useParallax } from '../../../utils/animationUtils';

export default function TheCraft() {
  const containerRef = useRef(null);
  const parallaxARef = useRef(null);
  const parallaxBRef = useRef(null);

  const attachParallax = useParallax({ strength: 0.12, threshold: 0.12 });
  const attachParallaxStrong = useParallax({ strength: 0.22, threshold: 0.12 });

  useEffect(() => {
    const cleanupA = attachParallax(parallaxARef.current);
    const cleanupB = attachParallaxStrong(parallaxBRef.current);
    return () => {
      cleanupA();
      cleanupB();
    };
  }, [attachParallax, attachParallaxStrong]);

  const steps = [
    {
      title: 'Sourcing the Finest',
      description: 'We handpick premium cocoa beans from sustainable farms across Ecuador, Ghana, and Madagascar, ensuring ethical practices and exceptional quality.',
      image: '/images/optimized/img-b9c821119035-640.webp',
      icon: 'ri-plant-line'
    },
    {
      title: 'Artisan Roasting',
      description: 'Our master chocolatiers roast each batch to perfection, unlocking complex flavor profiles and aromatic notes that define our signature taste.',
      image: '/images/optimized/img-cc1dac2c3b3d-640.webp',
      icon: 'ri-fire-line'
    },
    {
      title: 'Precision Crafting',
      description: 'Using time-honored techniques combined with modern innovation, we transform raw cocoa into liquid gold, carefully tempering and molding each creation.',
      image: '/images/optimized/img-f708e7800789-640.webp',
      icon: 'ri-hammer-line'
    },
    {
      title: 'The Final Touch',
      description: 'Every product is finished by hand, garnished with premium ingredients, and packaged with care to deliver an unforgettable experience.',
      image: '/images/optimized/img-6f01ae598b8b-640.webp',
      icon: 'ri-gift-line'
    }
  ];

  return (
    <section id="about-us" ref={containerRef} className="relative py-16 px-4 md:px-8 overflow-hidden">
      <div className="max-w-7xl mx-auto">
        <motion.div
          className="text-center mb-24"
          initial={{ opacity: 0, y: 30 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
        >
          <h2 className="text-3xl md:text-4xl font-serif text-[#C5A021] mb-3">The Craft</h2>
          <p className="text-lg text-[#F8F4F0]/70 font-light max-w-2xl mx-auto">
            From bean to bar, every step is a testament to our commitment to excellence and passion for chocolate
          </p>
        </motion.div>

        <div className="space-y-32">
          {steps.map((step, index) => (
            <motion.div
              key={index}
              className={`grid md:grid-cols-2 gap-16 items-center ${index % 2 === 1 ? 'md:flex-row-reverse' : ''}`}
              initial={{ opacity: 0, y: 50 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, margin: '-100px' }}
              transition={{ duration: 0.8, delay: 0.2 }}
            >
              <motion.div
                className={`relative ${index % 2 === 1 ? 'md:order-2' : ''}`}
                initial={{ opacity: 0 }}
                whileInView={{ opacity: 1 }}
                viewport={{ once: true }}
                transition={{ duration: 0.6 }}
              >
                <div ref={index % 2 === 0 ? parallaxARef : parallaxBRef} className="relative w-full h-96 rounded-3xl overflow-hidden border border-[#C5A021]/20">
                  <ResponsiveImage
                    src={step.image}
                    alt={step.title}
                    className="w-full h-full object-cover"
                    sizes="(max-width: 768px) 100vw, 50vw"
                    priority={index === 0}
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-[#140B07] via-transparent to-transparent"></div>
                </div>

                <motion.div
                  className="absolute -bottom-6 -right-6 w-24 h-24 bg-[#C5A021] rounded-full flex items-center justify-center will-change-temp"
                  whileHover={{ scale: 1.08, rotate: 180 }}
                  transition={{ duration: 0.5 }}
                >
                  <i className={`${step.icon} text-4xl text-[#140B07]`}></i>
                </motion.div>
              </motion.div>

              <div className={index % 2 === 1 ? 'md:order-1' : ''}>
                <motion.div
                  className="inline-block px-4 py-2 bg-[#C5A021]/20 rounded-full mb-6"
                  initial={{ opacity: 0, x: -20 }}
                  whileInView={{ opacity: 1, x: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.6, delay: 0.3 }}
                >
                  <span className="text-sm font-semibold text-[#C5A021]">Step {index + 1}</span>
                </motion.div>
                <motion.h3
                  className="text-4xl md:text-5xl font-serif text-[#F8F4F0] mb-6"
                  initial={{ opacity: 0, x: -20 }}
                  whileInView={{ opacity: 1, x: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.6, delay: 0.4 }}
                >
                  {step.title}
                </motion.h3>
                <motion.p
                  className="text-lg text-[#F8F4F0]/70 leading-relaxed"
                  initial={{ opacity: 0, x: -20 }}
                  whileInView={{ opacity: 1, x: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.6, delay: 0.5 }}
                >
                  {step.description}
                </motion.p>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
